export const secciones: DocumentoSeccion[] = [
  {
    titulo: "Título I",
    bloques: [
      { tipo: 'texto', texto: "Denominación, Tipo de Sindicato y Ámbito territorial de actuación." },
      { tipo: 'articulo', numero: "1", texto: "La denominación será Federación de Psicólogos de Venezuela, en adelante FPV, y constituye una corporación de carácter profesional y gremial, con personalidad jurídica y patrimonio propio, sin fines de lucro, constituida por los Colegios de Psicólogos y Delegaciones de Psicólogos, a nivel nacional, de acuerdo a lo pautado en la Ley de Ejercicio de la Psicología y ejerce las atribuciones que le otorga la Ley Orgánica del Trabajo, las Trabajadoras y los Trabajadores. Domicilio" },
      { tipo: 'articulo', numero: "2", texto: "La FPV, tiene su Sede en la Capital de la República, sin perjuicio de establecerse en una localidad que por su situación, para efectos prácticos, pudiere favorecer su funcionamiento. Objeto" },
      { tipo: 'articulo', numero: "3", texto: "La FPV como organización gremial tiene carácter permanente y tiene por objeto el estudio, defensa, desarrollo y protección del proceso social de trabajo, la protección, defensa y promoción de los intereses de sus Agremiados y Agremiadas, profesionales de la Psicología, del conjunto del pueblo, de la independencia y soberanía nacional conforme a la Constitución de la República Bolivariana de Venezuela. Finalidades" },
      { tipo: 'articulo', numero: "4", texto: "Son fines de la Federación de Psicólogos de Venezuela: • La defensa de la moral y la dignidad Profesional. • Promover la capacitación y especialización del Profesional de la Psicología, así como la defensa y proyección de la actividad científica de la Psicología. • La defensa de los intereses económicos, sociales y gremiales de la profesión. • El fomento de nexos y vínculos de solidaridad y mutua ayuda entre los Psicólogos que la integren. • Promover la fundación, constitución, desarrollo, fortalecimiento y relaciones con las Sociedades Científicas, adscritas a la Federación. • La creación y aplicación de un Sistema y Baremo que organice y reconozca las Especializaciones del ejercicio de la Psicología, en base a sus títulos académicos y/o experiencia profesional. • La promoción ante la sociedad y las instituciones nacionales, del reconocimiento a la misión que cumple la profesión del Psicólogo. • El fomento y desarrollo del estudio de las Ciencias en general y de la Psicología en particular. • El establecer relaciones de carácter científico, social y gremial con las Asociaciones Profesionales y organizaciones gremiales de cobertura nacional e internacional. • La defensa jurídica del Psicólogo, derivadas del ejercicio de la profesión y que provengan de la observancia del secreto Profesional y cualquiera otra propia del cumplimiento de la Ley de Ejercicio de la Psicología y del Código de Ética. • Respaldar, organizar y reglamentar, las actividades gremiales y sindicales, ante las autoridades patronales, de conformidad con la Ley Orgánica del Trabajo, las Trabajadoras y los Trabajadores. • Hacer respetar las normas de contratación, en lo que se refiere a nombramientos, movimientos de personal, ascensos, los problemas laborales y despidos injustificados. • Organizar y acreditar toda actividad que procure el mejoramiento profesional del Psicólogo a través de Congresos, Seminarios, Jornadas, Simposios, Mesas Redondas, Talleres y cualquier otra opción que enriquezca el acervo científico y profesional. • Instrumentar un procedimiento para conferirle a las actividades de Mejoramiento Profesional aprobadas por la Federación un valor conocido como Horas Crédito, tanto para participantes, como Expositores o Facilitadores que le sirvan de aval de su reconocida capacitación, así como, para las opciones de ascensos y otras que ameriten distinción. • Desarrollar acciones dirigidas al abordaje del intrusismo. • Impulsar la producción de publicaciones periódicas que le sirvan de órganos de difusión, como también para organizar y acrecentar su biblioteca. • Promocionar y apoyar el estudio y redacción de anteproyectos de leyes y Estatutos relacionados con los problemas sociales, políticos, laborales, económicos, culturales, científicos y educativos del país. Atender y tomar parte activa en las consultas que le sean sometidas a su consideración, sobre estas materias. • Promover ante las autoridades competentes, por medio de la Junta Directiva, todo lo que se juzgue conveniente a los intereses de la Profesión de la Psicología. • Asesorar y coadyuvar a la Administración Pública, para el mejor cumplimiento de las Leyes. Decretos, y demás disposiciones relacionadas con el ejercicio de la Psicología. • Defender los intereses comunes de sus agremiados y procurar el mejoramiento socioeconómico de los mismos a través de la elaboración, amparo y respaldo de los Convenios Colectivos y cualquier otra posición que favorezca al Psicólogo. • Velar por el cumplimiento de la deontología de la profesión sancionado en el Código de Ética del Psicólogo. • Cualquiera otra que asignen las Leyes, la Asamblea Nacional de la FPV y el Consejo Nacional. Atribuciones" },
      { tipo: 'articulo', numero: "5", texto: "Corresponde a la Federación de Psicólogos de Venezuela: • Fomentar el espíritu de solidaridad entre sus agremiados y propender a la defensa de sus miembros. • Mantener una estrecha vigilancia sobre la disciplina y el cumplimiento de la deontología de la Profesión, sancionado en el Código de Ética del Psicólogo. • Firmar los Convenios Colectivos en representación de todos sus agremiados o cualquier otro convenio entre la Federación y organismos públicos o privados que contraten Profesionales de la Psicología. Los Colegios de Psicólogos activos y Delegaciones de Psicólogos de cada Estado, podrán estar plenamente facultados por delegación formal de la Junta Directiva, para representar a la Federación de Psicólogos de Venezuela ante las autoridades estadales. En el caso que la Institución tuviere sólo carácter local, el Colegio de Psicólogos o Delegación, asumirá la representación de los agremiados, previa consulta y aprobación de la Junta Directiva FVP. • Defender al Profesional de la Psicología ante el Estado Venezolano, de las exoneraciones fiscales que se derivan de la aplicación del Art. 3 de la Ley de Ejercicio de la Psicología. • Celebrar el Día Nacional del Psicólogo, evento de carácter científico, cultural, gremial y social, que se celebra el 22 de Noviembre de cada año. Durante ésta Celebración, impondrá la Condecoración \"Honor al Mérito\" a aquellos Profesionales de la Psicología, que cumpliendo con el Art. 13 del Código de Ética, hayan desarrollado meritoria labor en cualquiera de los campos de acción del Psicólogo, de acuerdo al Comité Evaluador de la Condecoración, nombrado para tal efecto, por la Junta Directiva de la Federación. El Comité Evaluador de Condecoraciones se regirá por el Estatuto por la Junta Directiva de la FPV para los otorgamientos de estas distinciones. • Las demás atribuciones que les señalan las Leyes y sus Estatutos. Patrimonio" },
      { tipo: 'articulo', numero: "6", texto: "El patrimonio de la Federación de Psicólogos de Venezuela, está constituido por • Los ingresos por concepto de las alícuotas que deben cancelar los Colegios y Delegaciones de Psicólogos y el INPREPSI, de las cuotas gremiales especificadas en este Estatuto. • Los aportes que hagan instituciones públicas, privadas o personas naturales. • Los ingresos que se obtengan por la tramitación de Títulos, emisión de constancias, carnets, certificados y otros documentos que soliciten sus agremiados. • Los ingresos producto de las ventas de publicaciones y material promocional institucional. • Ingresos por el pago de servicios u otras actividades por parte del Estado, Instituciones públicas, privada y personas naturales. • Los ingresos por concepto de asesorías, cursos, talleres, o cualquier otra actividad organizada por la Federación de Psicólogos de Venezuela en pro de los agremiados, la comunidad y la sociedad. • Las donaciones hechas a nombre de la Federación de Psicólogos de Venezuela. • Los bienes muebles e inmuebles obtenidos por compra, donación o algún otro procedimiento legal. Cuotas Sindicales Monto y periodicidad de las cuotas ordinarias y forma de revisarlas." },
      { tipo: 'articulo', numero: "7", texto: "Las cuotas ordinarias la constituirán los ingresos que se obtengan por los derechos de inscripción en la FPV, la cual consiste en un pago único que se presenta ante la Asamblea Nacional para su aprobación. Autonomía administrativa" },
      { tipo: 'articulo', numero: "8", texto: "La FPV como organización sindical tiene derecho a organizar su gestión, administrar sus fondos y a su independencia financiera. Los psicólogos(as) agremiados(as) que cumplan con lo establecido en el Artículo 18 del presente Estatuto tienen derecho a solicitar la rendición de cuentas sobre la administración de los fondos de la FPV. Lo relativo al financiamiento de la FPV, así como el presupuesto y contraloría, serán regulados en estos estatutos. Movilización de los fondos" },
      { tipo: 'articulo', numero: "9", texto: "Los fondos deberán depositarse en una institución bancaria a nombre de la Federación de Psicólogos de Venezuela. Lo recaudado por cuotas ordinarias y extraordinarias deberá depositarse directamente en la cuenta a nombre de la FPV. No podrá mantenerse dinero efectivo en la caja de Federación de Psicólogos de Venezuela una cantidad que exceda de diez (10) Unidades Tributarias. Dicho monto será considerado trimestralmente en reuniones de Junta Directiva para su ajuste. Los fondos de la Federación de Psicólogos de Venezuela no podrán ser movilizados, ni efectuarse de ellos pago alguno, sino mediante instrumento firmado conjuntamente por dos firmas indistintas de los tres (3) miembros: Presidente, Vicepresidente y Tesorero, que la Junta Directiva formalice ante la institución bancaria. Rendición de cuentas" },
      { tipo: 'articulo', numero: "10", texto: "La Junta Directiva está obligada cada año a rendir cuenta de la administración de los fondos y bienes del FPV en Asamblea Nacional, y publicará una copia del Informe Administrativo que proyecte presentar, con una antelación mínima de quince días a la fecha en que vaya a celebrarse la misma, en los medios informativos institucionales para ser examinada por los agremiados(as). Los Directivos y las Directivas de la FPV que de acuerdo a este estatuto sean responsables de la administración y movilización de los fondos de la organización y no hayan cumplido esta obligación, no podrán ser reelectos como Directivos o Directivas de la FPV. Revisión por Contraloría General de la República" },
      { tipo: 'articulo', numero: "11", texto: "Podrán acudir ante la Contraloría General de la República no menos del diez por ciento (10%) de los Psicólogos(as) Agremiados(as) Activos de la FPV, a fin de solicitar que se auditen las cuentas presentadas por la Junta Directiva respectiva o ante la falta de rendición de cuentas en el período establecido Ilícitos en el manejo de fondos de la FPV" },
      { tipo: 'articulo', numero: "12", texto: "Los(as) Psicólogos(as) integrantes de la Junta Directiva y representantes gremiales designados que abusen de los beneficios derivados de la libertad sindical para su lucro o interés personal, serán sancionados(as) de conformidad con la Ley. Los(as) Psicólogos(as) integrantes de la Directiva de la FPV estarán obligados(as) a hacer declaración jurada de bienes al inicio de su gestión, una vez sean juramentados por la Comisión Electoral Central. Todos los pagos provenientes de obligaciones derivadas de la negociación colectiva o de cláusulas sindicales deben realizarse a nombre de la FPV y hacerse del conocimiento de los agremiados(as) Causas y procedimientos para aprobar cuotas extraordinarias" },
      { tipo: 'articulo', numero: "13", texto: "Las cuotas extraordinarias serán aprobadas en Asamblea Nacional Ordinaria o Extraordinaria cuando lo amerite para: • Mejorar y/o reparar la Infraestructura de la sede de la FPV. • Apoyar la gestión de la participación en Convenciones Colectivas. • Incorporar y reparar bienes de la FPV. • Cualquier otro motivo justificado que la Junta Directiva o los Asambleístas consideren conveniente." },
    ],
  },
  {
    titulo: "Título II",
    bloques: [
      { tipo: 'texto', texto: "CONDICIONES DE ADMISIÓN PARA LOS(AS) AGREMIADOS(AS) Derechos y Obligaciones para las Agremiadas y Agremiados." },
      { tipo: 'articulo', numero: "14", texto: "Es condición indispensable de admisión que se trate de un profesional de la Psicología, quien haya obtenido el Título de Licenciado en Psicología o Psicólogo, en Universidades reconocidas y autorizadas por el Consejo Nacional de Universidades (CNU) y demás leyes de la República Bolivariana de Venezuela, que ejerzan o no la profesión y cumplan los requisitos señalados en los Artículos 2 y 5 de la Ley de Ejercicio de la Psicología. Los Psicólogos egresados en Universidades extranjeras deben revalidar sus Títulos ante la Comisión de Reválidas y Equivalencias de la Universidad Central de Venezuela (UCV) antes de solicitar su inscripción en este gremio. Requisitos para el ejercicio de la Psicología" },
      { tipo: 'articulo', numero: "15", texto: "Para poder ejercer en la República Bolivariana de Venezuela los Profesionales de la Psicología deben inscribirse en el Colegio de Psicólogos de la jurisdicción donde estén ejerciendo (en caso de no hacerlo, donde estén domiciliados y/o residenciados), en el Instituto de Previsión Social del Psicólogo (INPREPSI) y en la Federación de Psicólogos de Venezuela (FPV) . El Colegio respectivo tramitará su registro ante la Federación de Psicólogos de Venezuela y ésta ante el Ministerio del Poder Popular para la Educación Universitaria, en acatamiento a la Ley del Ejercicio de la Psicología y del Código de Ética Profesional, siguiendo los procedimientos señalados en el Manual de Normas y Procedimientos Administrativos de la Federación de Psicólogos de Venezuela." },
      { tipo: 'articulo', numero: "16", texto: "La FPV otorgará al Agremiado un número de registro (Nª FPV). Sólo después de haber obtenido este número, el profesional de la Psicología podrá ejercer plenamente y gozar de sus derechos gremiales. Este número es de uso obligatorio en sus actuaciones profesionales, académicas, científicas y gremiales." },
      { tipo: 'articulo', numero: "17", texto: "Para dar cumplimiento al Art 5 de la Ley de Ejercicio de la Psicología, en lo relativo a la Inscripción en el Ministerio del Poder Popular para la Educación Universitaria se tramitará a través de la Federación, previa inscripción en el Instituto de Previsión Social del Psicólogo (INPREPSI) y en el Colegio de Psicólogos de su jurisdicción o en su defecto a la Delegación adscrita a este Colegio o al Colegio de Psicólogos más cercano a la jurisdicción donde ejerce. La Asamblea Nacional establecerá el arancel respectivo por esta gestión. Los psicólogos(as) deberán entregar al Colegio de Psicólogos, el Título previamente registrado en el Registro Principal correspondiente, y los demás requisitos establecidos en el Manual de Normas y Procedimientos de la **FPV.**" },
      { tipo: 'articulo', numero: "18", texto: "Se considera Psicólogo Agremiado Activo, con todos los Deberes y Derechos, aquel agremiado que esté registrado en la Federación de Psicólogos de Venezuela, inscrito en el Ministerio del Poder Popular para la Educación Universitaria, tenga asignado el N° de FPV, esté inscrito y solvente en el Colegio de Psicólogos de la jurisdicción donde estén ejerciendo (en caso de no hacerlo, donde estén domiciliados y/o residenciados), esté inscrito y solvente en el INPREPSI y no esté suspendido en el ejercicio profesional por un Tribunal Disciplinario." },
      { tipo: 'articulo', numero: "19", texto: "Los Profesionales de la Psicología, graduados en el exterior, que no hayan revalidado su Título, deberán acogerse a lo contemplado en el Art 4 de la Ley de Ejercicio de la Psicología. En caso de que un Profesional de la Psicología graduado en el exterior sea requerido para ser contratado por una Institución, pública o privada, el Colegio de Psicólogos respectivo solicitará a la Federación una Constancia de Inscripción Temporal, específica para el objeto de la Contratación, sólo por el tiempo de duración de su Contrato. Esta Constancia de inscripción debe ser aprobada por la Junta Directiva de la FPV. Estos Psicólogos no podrán ejercer actividad alguna en el ámbito gremialista." },
    ],
  },
  {
    titulo: "Título III",
    bloques: [
      { tipo: 'texto', texto: "DE LOS ÓRGANOS DE LA FEDERACIÓN DE PSICÓLOGOS DE VENEZUELA" },
      { tipo: 'articulo', numero: "20", texto: "Son Órganos de la Federación de Psicólogos de Venezuela la Asamblea Nacional, el Consejo Nacional, la Junta Directiva y el Tribunal Disciplinario Nacional." },
      { tipo: 'capitulo', texto: "Capítulo I" },
      { tipo: 'articulo', numero: "21", texto: "La Asamblea es el órgano supremo de la Federación de Psicólogos de Venezuela y estará integrada por la Junta Directiva, por sus Ex-Presidentes, por los Colegios de Psicólogos Activos y Solventes a través de sus Presidentes o quien haga sus veces y sus Delegados Nacionales Principales electos, Activos y Solventes y por un representante de las Delegaciones en aquellos Estados donde no hubiere Colegio de Psicólogos, de conformidad con el Art 24 de la Ley de Ejercicio de la Psicología, quienes en adelante se denominaran Asambleístas." },
      { tipo: 'articulo', numero: "22", texto: "Para asistir a la Asamblea, es requisito indispensable que los participantes sean Miembros Activos, de acuerdo con el artículo 18 de estos Estatutos." },
      { tipo: 'articulo', numero: "23", texto: "Los Colegios de Psicólogos serán los únicos responsables de la solvencia del Profesional de la Psicología con la Federación de Psicólogos de Venezuela. Las cuotas por este concepto deberán cancelarse trimestralmente por los Colegios." },
      { tipo: 'articulo', numero: "24", texto: "Los Colegios de Psicólogos que no estén solventes con la Federación de Psicólogos de Venezuela, para el trimestre anterior a la fecha de las Asambleas Nacionales Ordinarias y Extraordinarias, así como de los Consejos Nacionales, no deberán ser considerados a efectos del número que sirva de referencia para establecer el quórum reglamentario. Tampoco se considerarán para efectos del quórum reglamentario, los Colegios o Delegaciones que se encuentren intervenidos, suspendidos o inoperantes oficialmente, para la fecha de la celebración de la Asamblea. Los Colegios de Psicólogos y Delegaciones que no tengan causa justificada para su insolvencia, serán motivo de sanciones, todo ello de conformidad con la Ley y el presente Estatuto. Los Delegados Miembros Activos, podrán participar en la Asamblea Nacional con voz y voto, aun si su Colegio de Psicólogos o Delegación, no está solvente con la Federación de Psicólogos de Venezuela, no así, para los miembros del Consejo Directivo del Colegio de Psicólogos que se encuentre insolvente. Reglas para la autenticidad de las actas de asambleas." },
      { tipo: 'articulo', numero: "25", texto: "La Asamblea se reunirá ordinaria y extraordinariamente en la oportunidad, con el quórum y demás requisitos que determine estos Estatutos, previa convocatoria por la Junta Directiva de la Federación de Psicólogos de Venezuela, de acuerdo lo previsto en los artículos 30 y 31 del presente Estatuto. Elección de los Delegados" },
      { tipo: 'articulo', numero: "26", texto: "Para la elección de los Delegados referidos en el Art. 24 de la Ley del Ejercicio de la Psicología, éstos se elegirán en la misma oportunidad en que se elijan las autoridades de los Colegios de Psicólogos, procediéndose con el siguiente criterio de agremiados inscritos por Colegio: Los Colegios que tengan en su registro: 1) hasta 500 Psicólogos, Un (1) Delegado y su suplente 2) entre 501 y 1000 Psicólogos, Dos (2) Delegados y sus suplentes 3) entre 1001 y 1500 Psicólogos, Tres (3) Delegados y sus suplentes 4) entre 1501 y 2000 Psicólogos, Cuatro (4) Delegados y sus suplentes 5) más 2001 Psicólogos, Cinco (5) Delegados y sus suplentes" },
      { tipo: 'articulo', numero: "27", texto: "Los Colegios de Psicólogos del País, luego de sus elecciones internas y realizada la proclamación, deberán enviar a la Federación de Psicólogos de Venezuela, el listado de los Psicólogos elegidos para Delegados Nacionales, en un lapso no mayor de treinta (30) días consecutivos al proceso de juramentación. Convocatorias a las Asambleas Ordinarias." },
      { tipo: 'articulo', numero: "28", texto: "Para efectos de la Asamblea Nacional Ordinaria, la Junta Directiva de la Federación de Psicólogos de Venezuela, convocará a los Colegios de Psicólogos del país, por los medios electrónicos e informativos institucionales, con noventa (90) días continuos de anticipación como mínimo. En estas convocatorias debe quedar precisada la Agenda, el día o días, las horas y el lugar. La Asamblea Nacional se reunirá en la Sede fijada en la Asamblea Nacional anterior, no pudiendo cambiarse la Sede sin la aprobación de los miembros de la Junta Directiva y de la mayoría absoluta de los Expresidentes de la FPV, de los Presidentes de los Colegios Psicólogos Activos y solventes y Delegados Nacionales Activos. El quórum reglamentario" },
      { tipo: 'articulo', numero: "29", texto: "El quórum reglamentario será el resultante de la mitad más uno de los Asambleístas Activos, entendida como la mayoría absoluta para la fecha de la convocatoria. De no cumplirse el quórum reglamentario para el momento de la primera convocatoria, la Junta Directiva dejará constancia de ello en el Acta de Asamblea y procederá a la segunda convocatoria. La segunda convocatoria será para la media hora inmediata subsiguiente a la anterior y en ese momento la Junta Directiva procederá constatar el quórum; de no estar presente el número de Asambleístas requerido, se procederá a la tercera convocatoria, dejando constancia de ello en el Acta de Asamblea. La Tercera Convocatoria será para la media hora inmediata subsiguiente a la anterior, se constatará el quórum, que no deberá ser menor del treinta por ciento (30%) de los Asambleístas Activos y esto quedará asentado en el Acta de Asamblea y se dará inicio a la Asamblea Nacional, con los presentes, que al concluir las jornadas de trabajo, firmarán el Acta de Asamblea. Este registro de firmas se efectuará primero en Documento certificado por la Junta Directiva con los datos de identificación de los Asambleístas (nombres y apellidos, número de cédula de identidad y número de FPV) y posteriormente se traslada al libro de Actas de Asamblea. Cuando por falta de quórum no pueda constituirse la Asamblea Nacional, podrá instalarse el Consejo Nacional, si hubiere el quórum reglamentario que pauta la Ley del Ejercicio de la Psicología y estos Estatutos. Acuerdos y Resoluciones" },
      { tipo: 'articulo', numero: "30", texto: "Los Acuerdos y Resoluciones que se tomen durante la Asamblea Nacional, serán por mayoría simple de votos de los asambleístas presentes. Los asambleístas podrán abstenerse en las votaciones y explicar el motivo de su abstención verbalmente y presentarla por escrito en el momento de la votación. Después de constituirse la Asamblea, sus Deliberaciones, Acuerdos y Resoluciones, serán igualmente válidas, siempre y cuando se mantenga el cincuenta por ciento (50%) del quórum original con el que se instaló." },
      { tipo: 'articulo', numero: "31", texto: "Los Acuerdos y Resoluciones de la Asamblea Nacional, son de obligatorio cumplimiento para todos los miembros de la Federación de Psicólogos de Venezuela, siempre que respondan a las directrices establecidas por la Ley del Ejercicio de la Psicología, estos Estatutos y el Código de Ética del Psicólogo. Atribuciones de la Asamblea Nacional" },
      { tipo: 'articulo', numero: "32", texto: "Son atribuciones de la Asamblea Nacional • Aprobar o improbar la Memoria e Informe Administrativo que anualmente (año calendario) debe presentar la Junta Directiva de la Federación de Psicólogos de Venezuela. Esta presentación debe hacerse en el primer trimestre del año calendario. • Aprobar o improbar el presupuesto anual que debe presentar la Junta Directiva de la Federación de Psicólogos de Venezuela. Esta presentación debe hacerse en el primer trimestre del año calendario. • Fijar la Asignación Mensual al cargo del Presidente de la Federación de Psicólogos de Venezuela y a todos aquellos que decida la Asamblea. • Aprobar o improbar los informes, reportes y ponencias que le fueren sometidos a consideración conforme al presente Estatuto. • Aprobar o improbar el informe de actuación y administrativo del Tribunal Disciplinario de la FPV. • Considerar, discutir, aprobar o improbar, las proposiciones que formulen los asambleístas. • Dictar, modificar y derogar Acuerdos, Resoluciones y otras Normas de carácter obligatorio, para los órganos de la Federación, para los Colegios y en general para los Psicólogos, siempre y cuando no colidan con las Leyes y Reglamentos en el marco de la Legislación venezolana. • Conocer de las actuaciones de los Colegios de Psicólogos. Una vez presentado y aprobado la Memoria e Informe Administrativo en Asamblea Estadal, enviar copia a la Junta Directiva de la FPV. • Fijar la cuota por concepto de inscripción de los (las) Agremiados (as) en los Colegios de Psicólogos a nivel Nacional. • Analizar y aprobar la creación de las Sociedades Científicas. • Conocer los informes anuales que presenten las Sociedades Científicas antes sus respectivas Asambleas, enviar copia a la Junta Directiva de la FPV. • Aprobar el Sistema y Baremo que organice y reconozca la Especializaciones del ejercicio de la Psicología, en base a sus títulos académicos y/o experiencia profesional. • Revisar, derogar y modificar el Código de Ética del Psicólogo, de acuerdo a lo pautado en la Ley y este Estatuto. • Designar la Comisión Electoral Central, para la elección de la Junta Directiva, del Tribunal Disciplinario, el Fiscal y su Suplente de la FPV. • Fijar la sede de la próxima Asamblea Nacional. • Sancionar, derogar y modificar los Estatutos de la Federación. • Sancionar el Estatuto Interno de Asambleas y de Debates. • Acordar las contribuciones de los Psicólogos Colegiados, los Colegios de Psicólogos, el Instituto de Previsión Social del Psicólogo, las Sociedades Científicas y cualquier otro organismo que fuere creado por la propia Federación para el mantenimiento de ésta y para la celebración de las Asambleas Nacionales. • Cualquier otra que señala la Ley de Ejercicio de la Psicología, y el presente Estatuto. Asambleas Nacionales Ordinarias, oportunidad y frecuencia." },
      { tipo: 'articulo', numero: "33", texto: "Las Asambleas Nacionales Ordinarias se realizarán una vez al año, dentro del primer trimestre de cada año calendario, previa convocatoria de la Junta Directiva de la Federación de Psicólogos de Venezuela, con noventa (90) días continuos de anticipación. *Parágrafo Único:* En el caso que la Junta Directiva de la Federación de Psicólogos de Venezuela no convoque a Asamblea Nacional Ordinaria, esto implicará que la Asamblea correspondiente se considere convocada de Hecho, para el último sábado (no feriado según calendario oficial) del mes de Marzo, a las 8:00 a.m., en la sede de la Federación de Psicólogos de Venezuela. Asambleas Nacionales Extraordinarias, oportunidad y frecuencia." },
      { tipo: 'articulo', numero: "34", texto: "Las Asambleas Nacionales Extraordinarias, podrán ser convocadas y sesionar cuantas veces sea necesario durante el año. Podrán convocarse por: • Resolución de la Asamblea Ordinaria o Extraordinaria. • Disposición del Junta Directiva de la Federación de Psicólogos de Venezuela. • A solicitud de los Colegios de Psicólogos Activos, por mayoría absoluta o por la mitad más uno, del número que sirva de referencia, realizada por escrito ante el Junta Directiva. • Resolución del Consejo Nacional. En estas Asambleas solo podrán considerarse las materias señaladas en la convocatoria, salvo decisión contraria de la propia Asamblea aprobado por mayoría absoluta. Integrantes de la Mesa Directiva de la Asamblea Nacional" },
      { tipo: 'articulo', numero: "35", texto: "La Asamblea Nacional tendrá una Mesa Directiva compuesta por los miembros de la Junta Directiva de la Federación (Principales o sus Suplentes)." },
      { tipo: 'articulo', numero: "36", texto: "El Presidente de la Junta Directiva de la Federación, es Presidente de la Mesa y el Director de Debates nato de la Asamblea y puede delegar algunas de sus atribuciones en cualquier Asambleísta. La Asamblea, designará al Secretario de la misma. Atribuciones del Presidente de la Asamblea" },
      { tipo: 'articulo', numero: "37", texto: "Son atribuciones del Presidente de la Asamblea: • Abrir las sesiones y salvo decisión contraria de la Asamblea, prorrogarlas, suspenderlas y clausurarlas. • Dirigir los debates: otorgar el derecho en el uso de la palabra y vigilar que se cumpla lo establecido en estos Estatutos sobre el número de intervenciones por cada tema. • Llamar al orden a los Asambleístas que infrinjan el derecho de los otros miembros, a intervenir y participar. • Acreditar con su firma, junto con la del Secretario, las Actas de las sesiones y los demás actos de la Asamblea. • Expedir las credenciales para quienes resulten miembros de la Comisión Electoral Central, de la Federación de Psicólogos de Venezuela. • Cualquier atribución no señalada expresamente a otro funcionario. *Parágrafo Único:* Sólo son delegables las atribuciones pautadas en los literales b y c. Atribuciones del Secretario de la Asamblea" },
      { tipo: 'articulo', numero: "38", texto: "Son atribuciones del Secretario de la Asamblea: • Constatar solvencias y el quórum para el inicio de la Asamblea • Distribuir el trabajo y la documentación propia del acto. • Leer el Acta de la Asamblea anterior, para la consideración y aprobación de los asambleístas. • Llevar el Acta de Asamblea. Podrá usar equipo de grabación y de transcripción, mediante aprobación de la Junta Directiva • Solicitar las proposiciones por escrito y los votos salvados. • Entregar las Actas, debidamente firmadas por él, junto con un documento que contenga nombre, firma e identificación de los asambleístas. Dicho documento se acepta como cumplimiento de la firma en el Libro de Actas, según lo contemplado en el artículo 29 de estos Estatutos. • Verificar el quórum cada vez que se lo indique el Presidente de Asamblea. • Cualquier otra que le asigne la Asamblea. Presentación y discusión de propuestas" },
      { tipo: 'articulo', numero: "39", texto: "Las propuestas deben ser presentadas por escrito y consignadas ante el Director de Debates. La Mesa Directiva podrá autorizar propuestas verbales, en casos especiales." },
      { tipo: 'articulo', numero: "40", texto: "Para ser discutida, toda propuesta debe tener el respaldo de la mayoría absoluta de los Asambleístas presentes." },
      { tipo: 'articulo', numero: "41", texto: "Las siguientes mociones se consideran preferentes en relación a la materia en discusión y serán objeto de decisión sin Debate: • Mociones de Orden: Que son las referentes a la observancia de estos Estatutos y del orden del Debate, las cuales resolverá el Presidente sin perjuicio de que el interesado apele a la Asamblea. • Mociones de Información: Hechas para la rectificación de datos inexactos utilizados en la argumentación de un orador; para solicitar la lectura de documentos referentes al asunto en poder de la Mesa o suministrados por un miembro de la Asamblea, respecto de las cuales sólo se concederá la palabra después que haya finalizado el orador de turno. • Mociones de Diferimiento: Por pase a una Comisión de Trabajo, o por aplazamiento de la discusión, las cuales solo se aprobarán por la mayoría absoluta de los miembros presentes. • Mociones de Cierre de Debate: Por considerarse suficientemente discutido el asunto, que solo se aprobará mediante mayoría absoluta de los miembros presentes." },
      { tipo: 'articulo', numero: "42", texto: "Toda propuesta podrá modificarse, con la anuencia del ponente. En caso contrario, la modificación se tendrá como nueva propuesta." },
      { tipo: 'articulo', numero: "43", texto: "Concluido el Debate, el Secretario dará lectura a las propuestas con sus modificaciones." },
      { tipo: 'articulo', numero: "44", texto: "Las votaciones serán públicas y usualmente se efectuarán levantando la mano. La Asamblea puede decidir que sean secretas y por escrito." },
      { tipo: 'articulo', numero: "45", texto: "Las intervenciones de los oradores procurarán ser breves y concisas y guardar en todo tiempo la mayor consideración y respeto hacia los presentes y no se permitirán alusiones personales o expresiones contrarias a lo establecido en nuestro Código de Ética." },
      { tipo: 'articulo', numero: "46", texto: "Todo asambleísta tendrá derecho de hablar, pero no hablará más de dos (2) veces sobre el mismo asunto, salvo que fuere autor de una proposición, en cuyo caso podrá hacer uso de la palabra una tercera vez Las explicaciones que se soliciten de un orador, no se computan a los efectos de esta disposición." },
      { tipo: 'articulo', numero: "47", texto: "Durante el acto de votación, ningún Asambleísta podrá ausentarse del salón, ni tampoco si en el tema sometido a votación, se produjera un reconteo de los votos. El reconteo se puede hacer por: empate, moción de información que modifique la información conocida o dudas en el conteo inicial. Anunciado el acto de votación, ningún orador podrá intervenir en forma alguna, excepto para denunciar un vicio en el proceso. *Parágrafo Único:* En el caso que al hacer reconteo de votos por empate éste persista, se procederá a diferir la propuesta objeto de votación." },
      { tipo: 'articulo', numero: "48", texto: "En el Acta se dejará constancia de la aceptación, o rechazo a las proposiciones, así como de las abstenciones." },
      { tipo: 'articulo', numero: "49", texto: "El Acta de la Asamblea será sometida a la consideración y aprobación de la próxima Asamblea, sea Ordinaria o Extraordinaria." },
      { tipo: 'capitulo', texto: "Capítulo II" },
      { tipo: 'articulo', numero: "50", texto: "El Consejo Nacional es el órgano que suple a la Asamblea Nacional durante los lapsos cuando esta no se encuentre reunida, o cuando la Asamblea Nacional no se haya podido constituir por falta de quórum y, existiera el quórum reglamentario para realizar un Consejo Nacional. Este Consejo Nacional se instalará con al menos por la mitad más uno del número de quórum reglamentario, sin necesidad de las convocatorias previas incluidas en estos Estatutos." },
      { tipo: 'articulo', numero: "51", texto: "El Consejo Nacional estará integrado por los miembros de la Junta Directiva de la Federación de Psicólogos de Venezuela, por los Presidentes de los Colegios de Psicólogos y representantes de las Delegaciones, o quienes hagan sus veces. Los Colegios de Psicólogos y las delegaciones deberán estar solventes hasta el trimestre anterior a la convocatoria." },
      { tipo: 'articulo', numero: "52", texto: "El Presidente de la Junta Directiva de la Federación de Psicólogos de Venezuela será el Presidente del Consejo Nacional. Convocatoria al Consejo Nacional" },
      { tipo: 'articulo', numero: "53", texto: "El Consejo Nacional se reunirá las veces que sea convocado por la Junta Directiva de la Federación de Psicólogos de Venezuela o cuando lo solicitare la mayoría absoluta de los Colegios de Psicólogos Activos o por lo menos la mitad más uno del número total de Colegios activos." },
      { tipo: 'articulo', numero: "54", texto: "Corresponde a las Asambleas Estadales de los Colegios de Psicólogos, autorizar la solicitud del Colegio, ante la Junta Directiva de la Federación de Psicólogos de Venezuela de convocar un Consejo Nacional. Esta solicitud por escrito deberá estar firmada por el Presidente y el Secretario del Consejo Directivo del Colegio respectivo" },
      { tipo: 'articulo', numero: "55", texto: "Cada vez que la Junta Directiva de la Federación de Psicólogos de Venezuela reciba una solicitud de un Colegio de Psicólogos activos para convocar un Consejo Nacional, deberá someterla a la consideración de los otros Colegios de Psicólogos activos en un lapso no mayor a quince (15) días continuos. Los Consejos Directivos de los Colegios a su vez, dispondrán de un lapso no mayor de cinco (5) días continuos para aprobar dicha solicitud por unanimidad. En el caso que se obtenga mayoría absoluta para la propuesta de los Colegios activos, la Junta Directiva de la Federación de Psicólogos de Venezuela procederá a la convocatoria del Consejo Nacional, en un plazo no mayor a quince (15) días continuos." },
      { tipo: 'articulo', numero: "56", texto: "El Consejo Nacional será convocado por escrito, con quince (15) días continuos de anticipación a la fecha fijada para la reunión, sin perjuicio de otros medios de notificación que haga la Junta Directiva de la Federación de Psicólogos de Venezuela." },
      { tipo: 'articulo', numero: "57", texto: "En la convocatoria se determinarán las materias a tratar, así como el día, hora y lugar de la reunión. Usualmente el Consejo Nacional se reunirá en la Sede de la Federación de Psicólogos de Venezuela, pero podrá hacerlo en otro lugar señalado en la convocatoria." },
      { tipo: 'articulo', numero: "58", texto: "Es requisito indispensable, para participar en las reuniones del Consejo Nacional, que sus miembros estén Activos y cumplan con el Artículo 18 de estos Estatutos." },
      { tipo: 'articulo', numero: "59", texto: "El Consejo Nacional sólo podrá sesionar cuando esté presente en el mismo, la mayoría absoluta de sus integrantes activos. En los Consejos Nacionales, se aplicará el quórum reglamentario establecido en estos Estatutos." },
      { tipo: 'articulo', numero: "60", texto: "Las decisiones del Consejo Nacional se tomarán por el voto de la mayoría absoluta de sus integrantes activos presentes" },
      { tipo: 'articulo', numero: "61", texto: "Son aplicables al Consejo Nacional, las disposiciones contenidas en el Título III, referente a la organización, dirección y conducción de las Asambleas, señaladas en estos Estatutos. Atribuciones" },
      { tipo: 'articulo', numero: "62", texto: "Son atribuciones del Consejo Nacional: • Velar por el cumplimiento de las Resoluciones, Acuerdos y demás Normas dictadas por la Asamblea Nacional y el Consejo Nacional. • Conocer en cada reunión del informe que sobre sus actividades, presente la Junta Directiva de la Federación de Psicólogos de Venezuela. • Conocer del informe que sobre sus actuaciones y actividades, presenten los Colegios de Psicólogos. • Conocer del informe del Colegio de Psicólogos a cuya solicitud, se originó el Consejo Nacional. • Aprobar o improbar el presupuesto anual que debe presentar la Junta Directiva de la Federación de Psicólogos de Venezuela • Conocer y decidir acerca de las cuestiones y materias que sean sometidas a su consideración por la Junta Directiva de la Federación, por los Colegios o por los Psicólogos interesados, que no sean del específico conocimiento de la Asamblea Nacional. • Autorizar la enajenación y gravamen de los bienes inmuebles de la Federación de Psicólogos de Venezuela. • Cualesquiera otras establecidas por la Ley y sus Estatutos" },
      { tipo: 'articulo', numero: "63", texto: "Las decisiones del Consejo Nacional de la FPV, son de obligatorio cumplimiento para todos los Psicólogos del País, ejerzan o no la Profesión, siempre que estas estén en concordancia a lo dispuesto en la Ley del Ejercicio de la Psicología, el presente Estatuto y el Código de Ética Profesional." },
      { tipo: 'articulo', numero: "64", texto: "Las actuaciones y decisiones del Consejo Nacional serán conocidas en todo caso, por la próxima Asamblea Nacional." },
      { tipo: 'capitulo', texto: "Capítulo III" },
      { tipo: 'articulo', numero: "65", texto: "La Junta Directiva de la Federación de Psicólogos de Venezuela, es el órgano ejecutivo de la misma y tendrá su Sede en la Capital de la República. Podrá sesionar en cualquier otra ciudad del país cuando lo apruebe la Junta Directiva de la Federación de Psicólogos de Venezuela. Constitución de la Junta Directiva." },
      { tipo: 'articulo', numero: "66", texto: "La Junta Directiva, estará constituida por un Presidente, un Vicepresidente, un Secretario General, un Tesorero, cinco vocales y cinco suplentes, tendrán a su cargo la Dirección y Administración de la misma. Los suplentes cubrirán las ausencias temporales de los miembros principales y los vocales, en la forma prevista en estos Estatutos y en el Reglamento Electoral." },
      { tipo: 'articulo', numero: "67", texto: "En caso de que se agotare la lista de los suplentes, se procederá a lo pautado en el Reglamento Electoral" },
      { tipo: 'articulo', numero: "68", texto: "Los procesos electorales para la renovación de las autoridades de la Federación de Psicólogos de Venezuela se realizarán cada dos (2) años, por votación universal, directa y secreta, y se aplicará un sistema electoral mixto que combina la nominalidad con la representación proporcional de las minorías, mediante la aplicación del cociente electoral, empleando el método D’Hondt. Facultades de la Junta Directiva" },
      { tipo: 'articulo', numero: "69", texto: "La Junta Directiva tendrá amplias facultades para ejecutar actos de administración y disposición, de acuerdo con la Ley del Ejercicio de la Psicología y el presente Estatuto. Tendrá además las siguientes atribuciones: • Cumplir y hacer cumplir la Ley del Ejercicio de la Psicología, el Código de Ética Profesional del Psicólogo y este Estatuto. • Cumplir y hacer cumplir los fines de la Federación, los Acuerdos y Resoluciones de la Federación de Psicólogos de Venezuela, de la Asambleas Nacionales y de los Consejos Nacionales. • Analizar y emitir opinión sobre la interpretación de las Normas de Ética Profesional, cuando le fuere solicitado por algún Colegio de Psicólogos y proponer las reformas al Código de Ética Profesional. • Convocar las Asambleas Nacionales, Ordinarias y Extraordinarias y el Consejo Nacional, de acuerdo a lo previsto en la Ley y éste Estatuto. • Elaborar el proyecto de presupuesto de ingresos y gastos de la Federación de Psicólogos de Venezuela. • Fijar las dietas, viáticos y cuotas de remuneración específicas que deban cobrar los Psicólogos, en el cumplimiento de funciones que le asigne la Junta Directiva de la Federación de Psicólogos de Venezuela. • Administrar los fondos de la Federación de Psicólogos de Venezuela, ajustándose al presupuesto que apruebe la Asamblea Nacional. Cualquier modificación podrá hacerse previa autorización de la Asamblea Nacional o el Consejo Nacional. • Establecer y mantener relación con Organizaciones profesionales, gremiales, educativas, culturales, jurídicas, sociales comunitarias, laborales, nacionales e internacionales. Especialmente con las autoridades universitarias, donde se forman Profesionales de la Psicología, así como con los estudiantes y graduandos, para el logro de una mayor integración y participación. • Presentar un informe de su gestión anual, ante una Asamblea Nacional Ordinaria que se convocará para el primer trimestre de cada año. • Nombrar los Delegados Gremiales que considere pertinentes y designar los Delegados especiales que requiera para su representación, ante las instituciones y las autoridades que tengan relación con las actividades de la Federación. • Acreditar y respaldar a los Delegados Gremiales que sean elegidos por los Psicólogos de las Instituciones. • Designar los miembros de las Comisiones de Trabajo Permanentes y Especiales, para el mejor logro de los objetivos de la Federación de Psicólogos de Venezuela. • Proceder a la designación y remoción de las Comisiones. • Contratar y convenir la remuneración del personal de Profesionales de la Psicología y otras profesiones universitarias, así como del personal técnico y de secretaría, que fuere necesario para cumplir los fines de la Federación. • La Junta Directiva asumirá la representación gremial y sindical de los Convenios Colectivos Nacionales y de otras materias de carácter gremial o laboral, a solicitud de los Colegios o cuando lo considere necesario, en el resguardo de los intereses, el respeto y consideración que se merecen los agremiados. • Las gestiones de carácter administrativo, que involucren los bienes inmuebles, la venta o permuta de los mismos y la adquisición de servicios debe ser aprobada por el Consejo Nacional e informará de tal gestión, a la Asamblea Nacional. • Conocer de las apelaciones que le correspondiere conocer, en virtud de sus propias decisiones • La Junta Directiva de la Federación, podrá crear Secretarías con fines específicos, a objeto de cubrir las necesidades de la organización. Estas Secretarías podrán ser cubiertas por los vocales u otro Profesional de la Psicología idóneo para tal designación, en la forma que decida la Junta Directiva de la Federación. • Crear y actualizar el Manual de Normas y Procedimientos Administrativos. • Cualesquiera otras atribuciones que le señalen la Ley Orgánica del Trabajo, las Trabajadoras y los Trabajadores, la Ley de Ejercicio de la Psicología, el presente Estatuto, la Asamblea Nacional y el Consejo Nacional." },
      { tipo: 'articulo', numero: "70", texto: "La Junta Directiva se reunirá al menos una vez por mes, en el día y la hora que se fije, o las veces que queden acordadas por la misma Junta Directiva. Podrán reunirse extraordinariamente las veces que sean convocados por su Presidente o a solicitud de mínimo tres miembros principales." },
      { tipo: 'articulo', numero: "71", texto: "Las sesiones de la Junta Directiva serán privadas y restringidas a sus miembros. Sin embargo, será posible la asistencia de las personas que sean invitados a asistir y/o participar. De cada sesión se levantará un Acta, suscrita por los miembros presentes." },
      { tipo: 'articulo', numero: "72", texto: "La Junta Directiva se considerará legalmente constituida con la asistencia de, por lo menos, seis (6) de sus miembros y sus decisiones se tomarán por la mayoría absoluta de los presentes. El miembro de la Junta Directiva que esté en desacuerdo con una decisión tomada por la mayoría, debe motivar su voto salvado por escrito lo cual constará en el Acta." },
      { tipo: 'articulo', numero: "73", texto: "Los miembros de la Junta Directiva están obligados a asistir a todas las sesiones. Además debe mantenerse en condición de miembro Activo. En caso contrario, no tendrá derecho a voz ni voto en las reuniones de la Junta Directiva." },
      { tipo: 'articulo', numero: "74", texto: "Solo los miembros principales de la Junta Directiva y los suplentes, cuando hayan sido convocados para sustituir a los principales, tendrán derecho a voz y voto. Los suplentes que estuvieren presentes durante las sesiones de la Junta Directiva, bien por invitación u ocasionalmente, o porque la Junta Directiva decidiera sesionar con todos sus miembros, solo tendrán derecho a voz." },
      { tipo: 'articulo', numero: "75", texto: "Se entenderá como ausencia temporal aquella debida a enfermedad o a otra causa debidamente justificada por escrito, así como la ausencia del país por motivos personales, académicos, profesionales y/o gremiales y la suspensión temporal de los derechos por el Tribunal Disciplinario. La ausencia temporal no excederá el 25% del período del tiempo establecido para su mandato." },
      { tipo: 'articulo', numero: "76", texto: "Se entiende por ausencia absoluta, el fallecimiento, la renuncia, el revocatorio del mandato, la interdicción judicial, la suspensión del ejercicio por el Tribunal Disciplinario, la condena penal, ausencia temporal justificada mayor al 25% del período de su mandato y la inasistencia injustificada a tres sesiones consecutivas de las reuniones de Junta Directiva, la suspensión del ejercicio profesional por decisión directa del Tribunal Disciplinario la cual será notificada al Ministerio del Poder Popular para la Educación Universitaria. *Parágrafo Único:*. La Junta Directiva podrá determinar otras causas de ausencias temporales o absoluta por decisión unánime de sus miembros." },
      { tipo: 'articulo', numero: "77", texto: "La inasistencia injustificada a cinco (5) reuniones no consecutivas de Junta Directiva, será considerada causal de destitución del cargo, por decisión de mayoría calificada (75%) del resto de los integrantes de la Junta Directiva." },
      { tipo: 'articulo', numero: "78", texto: "La suspensión de los derechos gremiales a que hace referencia el Artículo 35 de la Ley del Ejercicio de la Psicología será considerado como ausencia temporal. La suspensión del ejercicio profesional a que alude el mismo Artículo será considerado como ausencia absoluta." },
      { tipo: 'articulo', numero: "79", texto: "Son atribuciones del Presidente de la Junta Directiva: • Ejercer la Representación Jurídica y Social de la Federación de Psicólogos de Venezuela. • La custodia y archivo de los sellos y documentos que solo conciernen a la Federación, o que guardan relación con gestiones Legales y Profesionales, ante los organismos competentes, oficiales privados, nacionales o internacionales. • Delegar dicha representación, parcial o totalmente en el Vicepresidente o en cualquier otro miembro de la Junta Directiva, previa autorización de la Junta Directiva de la Federación. • Presidir las sesiones de la Junta Directiva. • Movilizar los fondos de la Federación de Psicólogos de Venezuela, conjuntamente con el Vicepresidente y el Tesorero. • Firmar la correspondencia, documentos, contratos, convenciones colectivas y demás escritos que por su cargo le conciernan. • Velar por la ejecución de las decisiones de la Junta Directiva. • Asignar actividades a los miembros de la Junta Directiva • Exhortar a los Consejos Directivos al cumplimiento de los deberes y fines. • Promover acciones, proyectos y cualquier actividad a favor del gremio. • Llamar a orden a cualquier miembro agremiado por desacato, infracción o conducta que lesión, interfiera o infrinja al gremio en general o a otro miembro de la Federación de Psicólogos de Venezuela. • Las demás que le señale estos Estatutos y otros textos legales de obligatorio cumplimiento." },
      { tipo: 'articulo', numero: "80", texto: "Son atribuciones del Vicepresidente de la Junta Directiva: • Suplir las ausencias temporales o absolutas del Presidente. • Colaborar con el Presidente en las funciones que éste le tiene asignadas, a solicitud del mismo. • Presidir las Comisiones de Trabajo que le asigne la Junta Directiva. • Movilizar los fondos de la Federación de Psicólogos de Venezuela, conjuntamente con el Presidente y el Tesorero. • Las demás que le sean asignadas por el Presidente o la Junta Directiva." },
      { tipo: 'articulo', numero: "81", texto: "Son atribuciones del Secretario General de la Junta Directiva: • Llevar con regularidad los libros no contables que sean necesarios para el funcionamiento de la Federación. • Dar cuenta a la Junta Directiva de la correspondencia recibida y redactar los proyectos de Actas de las sesiones. • Llevar el libro de Actas de las sesiones de la Junta Directiva, debidamente firmado al final de cada sesión, por los presentes. • Firmar la correspondencia de acuerdo a las normas e instrucciones que la Junta Directiva determine. • Redactar la correspondencia no atribuida al Presidente. • Las demás que le sean fijadas por la Junta Directiva o el Presidente." },
      { tipo: 'articulo', numero: "82", texto: "Son atribuciones del Tesorero de la Junta Directiva: • Movilizar los Fondos de la Federación, conjuntamente con el Presidente y el Vicepresidente • Mantener actualizado mensualmente los estados financieros e informar a la Junta Directiva. • Mantener al día los libros de contabilidad y la lista de los Colegios Activos. • Preparar el informe administrativo anual. • Elaborar el proyecto de presupuesto de la Federación, que será sometido a la consideración y aprobación de la Asamblea Nacional. • Solicitar a los Colegios y al INPREPSI, el pago de las cuotas y contribuciones para el mantenimiento de la Sede. • Las demás que le fije la Junta Directiva y el Presidente." },
      { tipo: 'articulo', numero: "83", texto: "Corresponde a los Vocales las siguientes funciones y atribuciones: • Presidir las Comisiones de Trabajo que le designe el Presidente o la Junta Directiva. • Presentar proyectos para la dirección y conducción del gremio. • Velar por el buen funcionamiento de la Federación de Psicólogos de Venezuela. • Otra que le fije la Junta Directiva o el Presidente." },
      { tipo: 'articulo', numero: "84", texto: "Las ausencias temporales y absolutas de los miembros de la Junta Directiva, serán cubiertas en el orden previsto en el Reglamento Electoral." },
      { tipo: 'articulo', numero: "85", texto: "En caso de ausencia absoluta del Presidente y del Vicepresidente, sus cargos serán suplidos transitoriamente por los suplentes, quienes deben proceder a convocar Asamblea Nacional Extraordinaria a fin de designar la Comisión Electoral Central la cual convocará a elecciones para estos dos (2) cargos según lo establecido en el Reglamento Electoral. De las elecciones" },
      { tipo: 'articulo', numero: "86", texto: "Los procesos electorales de la FPV se regirán conforme a lo establecido en su Reglamento Electoral" },
      { tipo: 'articulo', numero: "87", texto: "La Junta Directiva y el Tribunal Disciplinario de la F.P.V. ejercerán sus funciones durante el tiempo que establezca el presente Estatuto, pero en ningún caso podrá establecerse un período mayor a tres años." },
      { tipo: 'articulo', numero: "88", texto: "La FPV tiene derecho a efectuar sus procesos electorales, sin más limitaciones que las establecidas en las Leyes de la República Bolivariana de Venezuela y el presente Estatuto. La no convocatoria a elecciones por parte de los integrantes de una Junta Directiva a la que se le haya vencido el período para la cual fue electa es contraria a la ética sindical, al ejercicio de la democracia sindical y a lo establecido en la Constitución de la República Bolivariana de Venezuela." },
      { tipo: 'articulo', numero: "89", texto: "La Junta Directiva cuyo período haya vencido de conformidad con las leyes correspondientes y estos Estatutos, no podrán realizar, celebrar o representar a la FPV en actos jurídicos que excedan la simple administración, por tal razón, pierde las amplias facultades para ejecutar actos de administración y disposición señalados en el Artículo 69 del presente Estatuto." },
      { tipo: 'articulo', numero: "90", texto: "La Junta Directiva que tenga el período vencido no podrá sustituir a sus integrantes por mecanismos distintos al proceso de elecciones, ni modificar estos estatutos para prorrogar el periodo de la Junta Directiva. Forma de sustitución de los que hayan sido removidos, removidas, revocados, revocadas o hayan renunciado a su cargo antes del vencimiento del período estatutario de la Junta Directiva." },
      { tipo: 'articulo', numero: "91", texto: "Cuando durante el periodo estatutario de la Junta Directiva renunciaran, se ausentaran o fuesen removidos más de las dos terceras partes de sus integrantes, deberá convocarse al proceso electoral, según lo establecido en el Reglamento Electoral. Revocatoria del mandato de la junta directiva" },
      { tipo: 'articulo', numero: "92", texto: "Se establece la posibilidad de la revocatoria del mandato de la Junta Directiva mediante referéndum el cual no podrá ser convocado antes de que haya transcurrido más de la mitad del período para el cual fue electa. Este proceso revocatorio será reglamentado conforme a lo establecido en el Reglamento Electoral de la FPV." },
      { tipo: 'capitulo', texto: "Capítulo IV" },
      { tipo: 'texto', texto: "Objetivo, Integrantes, Funcionamiento" },
      { tipo: 'articulo', numero: "93", texto: "La organización y funcionamiento del Tribunal Disciplinario Nacional de la FPV y de los Tribunales Disciplinarios de los Colegios de Psicólogos se regirán por: La Ley de Ejercicio de la Psicología, el Código de Ética Profesional y el Reglamento de los Tribunales Disciplinarios. También se regirán por el Procedimiento Disciplinario acerca del cual son competentes los citados Tribunales. Objetivos" },
      { tipo: 'articulo', numero: "94", texto: "Al Tribunal Disciplinario de la Federación de Psicólogos de Venezuela le compete: 1. Conocer en Segunda Instancia de las decisiones definitivas de los Tribunales Disciplinarios de los Colegios de Psicólogos. 2. Inspeccionar y vigilar a los Tribunales Disciplinarios de los Colegios de Psicólogos por incumplimiento o negligencia manifiesta. 3. Conocer y sancionar a los Tribunales Disciplinarios de primera Instancia por abandono injustificado del caso. Integrantes" },
      { tipo: 'articulo', numero: "95", texto: "El Tribunal Disciplinario de la Federación de Psicólogos de Venezuela estará integrado por seis (6) miembros, tres (3) principales y tres (3) suplentes (cuyos cargos se escogerán en su propio seno), un Fiscal Principal y su suplente. Funcionamiento" },
      { tipo: 'articulo', numero: "96", texto: "El Tribunal Disciplinario funcionará en la misma sede de la Federación de Psicólogos de Venezuela, sesionando y actuando según las normativas establecidas en su Reglamento Interno. PARAGRÁFO ÚNICO: El Reglamento de los Tribunales Disciplinarios, tendrá su propia numeración aparte y sus artículos citados llevarán las siglas RTD, que indica Reglamento Tribunal Disciplinario Causas y procedimiento para la imposición de sanciones a los agremiados(as)" },
      { tipo: 'articulo', numero: "97", texto: "El Tribunal Disciplinario de la Federación de Psicólogos de Venezuela, conocerá en segunda instancia, de las infracciones a la Ley de Ejercicio de la Psicología y de todo lo previsto en el Artículo 2 del Reglamento de los Tribunales Disciplinarios." },
    ],
  },
  {
    titulo: "Título IV",
    bloques: [
      { tipo: 'articulo', numero: "98", texto: "Los Colegios de Psicólogos son Corporaciones de Profesionales, con personalidad jurídica y patrimonio propio, constituidas a los fines previstos en la Ley de Ejercicio de la Psicología." },
      { tipo: 'articulo', numero: "99", texto: "Son Órganos de los Colegios de Psicólogos la Asamblea, el Consejo Directivo y el Tribunal Disciplinario Estadal. *Parágrafo Único:* En los Estados donde no hubiese Colegio, los psicólogos que ejerzan en él, o que no ejerciendo, estén domiciliados en él, formarán una Delegación, la cual será adscrita al Colegio de la jurisdicción más cercana." },
      { tipo: 'articulo', numero: "100", texto: "Los Colegios de Psicólogos podrán ejercer dentro de la Federación, todos los Derechos que la Ley y estos Estatutos les acuerdan, y cumplir y hacer cumplir los Acuerdos, Resoluciones y demás Normas que dicten la Federación de Psicólogos, Asamblea Nacional, el Consejo Nacional y la Asamblea Estadal. *Parágrafo Único:* Se entenderá como Colegio de Psicólogos Activo, aquel que esté solvente en sus cuotas con la Federación." },
      { tipo: 'articulo', numero: "101", texto: "Los Reglamentos Internos de los Colegios de Psicólogos, serán dictados por sus respectivas Asambleas Estadales. Las Resoluciones y Acuerdos que dicten, deberán estar de conformidad con lo establecido por la Ley Orgánica del Trabajo, de las Trabajadoras y los Trabajadores, la Ley del Ejercicio de la Psicología, el presente Estatuto, el Código de Ética Profesional y demás Normas y Estatutos Estadales y Nacionales de la FPV." },
    ],
  },
  {
    titulo: "Título V",
    bloques: [
      { tipo: 'articulo', numero: "102", texto: "Para dar cumplimiento a los fines de la Federación de Psicólogos de Venezuela, está fomentará la creación, organización y fortalecimiento de Sociedades Científicas relacionadas con la Psicología como ciencia. Concepto" },
      { tipo: 'articulo', numero: "103", texto: "Se considera Sociedad Científica a toda aquella Asociación o Agrupación de Profesionales de la Psicología o afines que esté legalmente establecida con personalidad jurídica propia y que sus fines sean cónsonos con el desarrollo de la Psicología como Ciencia. Requisitos" },
      { tipo: 'articulo', numero: "104", texto: "La Junta Directiva de la Federación de Psicólogos de Venezuela establecerá un conjunto de requisitos que dará el aval y certificación a una Sociedad Científica, como agrupación acreditada ante la Sociedad. Fines, objetivos y propósitos" },
      { tipo: 'articulo', numero: "105", texto: "Los fines, objetivos y propósitos de las Sociedades Científicos acreditadas deben estar acordes con la Ley de Ejercicio de la Psicología, su Reglamento y el Código de Ética del Psicólogo" },
      { tipo: 'articulo', numero: "106", texto: "Las Sociedades Científicas avaladas y certificadas por la Junta Directiva de la Federación de Psicólogos de Venezuela, deben prestarle a esta su apoyo y colaboración en relación a información, asesoramiento y entrenamiento, difusión y formación en el área específica de su competencia." },
      { tipo: 'articulo', numero: "107", texto: "Las Sociedades Científicas podrán crear Capítulos en los diferentes Estados y los Colegios de Psicólogos correspondientes, deberán darle el apoyo necesario, para que estas funcionen." },
    ],
  },
  {
    titulo: "Título VI",
    bloques: [
      { tipo: 'texto', texto: "Categorías de Miembros" },
      { tipo: 'articulo', numero: "108", texto: "La Federación de Psicólogos de Venezuela tiene las siguientes categorías de Miembros, • Miembros Fundadores • Miembros Honorarios • Miembros Directivos • Miembros Ex- Directivos • Miembros Delegados • Miembros Agremiados Todos estos miembros serán Psicólogos Activos, que hayan cumplido con los requisitos de inscripción de acuerdo a la Ley del Ejercicio de la Psicología y estos Estatutos, excepto los miembros Honorarios." },
      { tipo: 'articulo', numero: "109", texto: "Son miembros Fundadores aquellos Psicólogos que en su oportunidad fundaron la Federación de Psicólogos de Venezuela." },
      { tipo: 'articulo', numero: "110", texto: "Son miembros Honorarios aquellas personas que no son Psicólogos, pero que han cooperado ampliamente con la Federación de Psicólogos de Venezuela y el gremio en general, a las cuales la Asamblea Nacional, por mayoría absoluta, les da tal distinción." },
      { tipo: 'articulo', numero: "111", texto: "Son miembros Directivos, todos los Psicólogos Activos que están desempeñando cargos en las Juntas Directivas, los Consejos Directivos, los Tribunales Disciplinarios y los Fiscales, en la Federación de Psicólogos de Venezuela, en los Colegios de Psicólogos y en el INPREPSI" },
      { tipo: 'articulo', numero: "112", texto: "Son Miembros Ex-Directivos, los Psicólogos que fueron electos y culminaron su periodo en los cargos representativos del artículo 111 de estos Estatutos." },
      { tipo: 'articulo', numero: "113", texto: "Son Miembros Delegados aquellos Psicólogos Activos que tienen una actividad representativa ante la Federación de Psicólogos de Venezuela y otras Instituciones y que se rigen por los requisitos establecidos en este Estatuto." },
      { tipo: 'articulo', numero: "114", texto: "Son Miembros Agremiados, los psicólogos que hayan cumplido con los requisitos de inscripción de acuerdo con la Ley del Ejercicio de la Psicología y estos Estatutos y que no están incluidos en alguna de las categorías anteriores señaladas en este Estatuto." },
      { tipo: 'articulo', numero: "115", texto: "Todos los Miembros Agremiados de la Federación de Psicólogos de Venezuela pueden estar en alguna de estas dos condiciones, según su cumplimiento con los deberes gremiales, pueden ser Miembro Activo o Miembro no Activo." },
      { tipo: 'articulo', numero: "116", texto: "Se considera Psicólogo Agremiado Activo, al profesional que reúne todas las condiciones señaladas en el artículo 18 de este Estatuto." },
      { tipo: 'articulo', numero: "117", texto: "Se considera Psicólogo Agremiado No Activo, al profesional que no se encuentra en las condiciones señaladas en el artículo 18 de este Estatuto." },
      { tipo: 'articulo', numero: "118", texto: "Son derechos de los Psicólogos Agremiados Activos: • Elegir y ser elegidos como integrantes de los Órganos de la Federación de Psicólogos de Venezuela, los Colegios de Psicólogos y el INPREPSI, de conformidad con la Ley y este Estatuto. • Integrar Comités, Comisiones y Delegaciones que sean nombradas por la Federación de Psicólogos de Venezuela, los Colegios de Psicólogos Activos y otros organismos gremiales. • Someter a la consideración de las Juntas Directivas y Consejos Directivos, cualquier problema gremial, laboral o profesional que confronte. • Obtener orientación jurídica y/o gremial en su ejercicio profesional. • Recibir gratuitamente y/o a precios especiales, publicaciones de la Federación de Psicólogos de Venezuela, los Colegios de Psicólogos de Venezuela y el INPREPSI, material profesional, Tests Psicológicos y otros beneficios que estos organismos acuerden para sus Agremiados • Obtener descuentos en Cursos, Talleres y otras actividades programadas por la Federación, los Colegios y el INPREPSI • Tener voz y voto en las Asambleas Estadales del Colegio de su adscripción y la Asamblea Nacional del INPREPSI • Utilizar los recursos proporcionados por la Federación, el Colegio de Psicólogos y el INPREPSI. para dictar, cursos, talleres, entre otros., con descuentos especiales. • Participar en los eventos sociales, deportivos, culturales, programados por la Federación, los Colegios y el INPREPSI. • Representar a los Psicólogos en su Institución, lugar de trabajo u otro organismo. • Participar en los Sistemas de Certificados Psicológicos organizados, instituidos y/o coordinados por la Federación de Psicólogos de Venezuela. • Integrar la representación gremial ante los claustros, asambleas y consejos de las facultades y escuelas de las universidades nacionales. • Disfrutar de los servicios y otros beneficios que pongan a disposición la Federación de Psicólogos de Venezuela, los Colegios y el INPREPSI." },
      { tipo: 'articulo', numero: "119", texto: "Son deberes de los Miembros Agremiados Activos cumplir con: • La Ley de Ejercicio de la Psicología. • Los Estatutos de la Federación de Psicólogos de Venezuela. • Los Reglamentos Internos de los Colegios de Psicólogos. • El Reglamento Interno del INPREPSI. • El Código de Ética Profesional del Psicólogo. • Los Acuerdos. Resoluciones, Disposiciones, Instructivos. Manuales de Normas y Procedimientos Específicos, y demás pronunciamientos de la Asamblea Nacional, de la Asamblea Estadal, de la Junta Directiva de la Federación de Psicólogos de Venezuela y el Consejo Directivo del Colegio de Psicólogos de adscripción. • Acatar las decisiones de los Tribunales Disciplinarios. • Ejercer la profesión decorosamente, enalteciéndola y rodeándola de prestigio. • Asistir a las Asambleas y demás actos promovidos por el Colegio de su adscripción. • Pagar con puntualidad las cuotas estatutarias y contribuciones debidamente sancionadas por la Federación, los Colegios y el INPREPSI. • Cancelar el monto correspondiente a las cuotas administrativas fijadas por la Junta Directiva y los Consejos Directivos. • Desempeñar con idoneidad los cargos que le fueren asignados, ya sean de carácter electivo o por designación de las Asambleas, las Juntas Directivas, o los Consejos Directivos u otros organismos. • Denunciar ante el Tribunal Disciplinario de su Colegio de Psicólogos de adscripción, cualquier violación que conozca de la Ley de Ejercicio de la Psicología, de estos Estatutos, del Reglamento Interno del Colegio de Psicólogos, del Código de Ética del Psicólogo y de los Acuerdos, Disposiciones, Instructivos. Manuales de Normas y Procedimientos específicos y Pronunciamientos emanados de las Asambleas, la Junta Directiva de la Federación, del INPREPSI y los Consejos Directivos de los Colegios de Psicólogos • Exigir a los Psicólogos no agremiados, que procedan a registrarse en la FPV" },
      { tipo: 'articulo', numero: "120", texto: "La Federación de Psicólogos de Venezuela, tendrá dentro de su cuerpo representativo, a sus Delegados, que tendrán tres características: • Los Delegados Nacionales: Son representantes electos de los Colegios de Psicólogos ante las Asambleas Nacionales de la Federación de Psicólogos de Venezuela. • Los Delegados Gremiales: Son aquellos que por acuerdo de un grupo de psicólogos se constituyen sus representantes ante una determinada institución. • Los Delegados Designados: Son los que integran las Comisiones Especiales de trabajo, conformadas por la Junta Directiva de la Federación de Psicólogos de Venezuela. Todos los Delegados deben estar en conformidad con la Ley de Ejercicio de la Psicología, el Código de Ética del Psicólogo y el presente Estatuto. *Parágrafo Único:* No se puede ejercer cargo directivo en la Federación de Psicólogos de Venezuela, el Tribunal Disciplinario Nacional, los Colegios de Psicólogos, los Tribunales Disciplinarios Estadales, las Fiscalías y simultáneamente, ser Delegado Nacional." },
      { tipo: 'articulo', numero: "121", texto: "En atención al Art. 24 de la Ley de Ejercicio de la Psicología, los Delegados a las Asambleas Nacionales, Principales y Suplentes, serán elegidos cada dos años, de acuerdo con lo establecido con el Reglamento Electoral vigente, en la misma oportunidad en que se elijan las autoridades de los Colegios de Psicólogos, el Consejo Directivo, el Tribunal Disciplinario y el Fiscal, y sus Suplentes." },
      { tipo: 'articulo', numero: "122", texto: "Los Delegados Gremiales serán designados por la Junta Directiva, para cumplir actividades específicas ante instituciones y autoridades competentes. También serán Delegados Gremiales los Psicólogos que sean electos por sus colegas, dentro de las Instituciones, para representar sus intereses ante la Federación y ante patronos. La acreditación de estos Delegados Gremiales será expedida por la Junta Directiva de la Federación de Psicólogos de Venezuela." },
      { tipo: 'articulo', numero: "123", texto: "Se considerarán Delegados de la Federación, los Psicólogos Activos que designe la Junta Directiva de la Federación de Psicólogos de Venezuela y los Consejos Directivos de los Colegios de Psicólogos Activos para integrar Comisiones Especiales de Trabajo, en cumplimiento de las atribuciones y objetivos de la Federación y de acuerdo a lo establecido en el Código de Ética y el presente Estatuto." },
      { tipo: 'articulo', numero: "124", texto: "Todos los Delegados para ser acreditados, deben recibir una credencial expedida de la Junta Directiva de la Federación de Psicólogos de Venezuela o por el Consejo Directivo de los Colegios respectivos." },
      { tipo: 'articulo', numero: "125", texto: "Los Delegados Nacionales, los Delegados Gremiales y los Delegados designados para integrar Comisiones Especiales de Trabajo de la Federación de Psicólogos de Venezuela, deberán, aceptar y cumplir las tareas que se le asignen." },
    ],
  },
  {
    titulo: "Título VII",
    bloques: [
      { tipo: 'articulo', numero: "126", texto: "El presente Estatuto es de obligatorio cumplimiento para todos los Psicólogos que hacen vida en el País ejerzan o no la profesión y sus infracciones serán objeto de sanción, si fuere el caso." },
      { tipo: 'articulo', numero: "127", texto: "Estos Estatutos podrán ser modificados total o parcialmente en Asamblea Nacional Extraordinaria convocada especialmente a tal efecto, a propuesta de la Junta Directiva, de la Asamblea Nacional o de la mayoría absoluta de los Colegios de Psicólogos activos del País. A los efectos de esta disposición, el quórum requerirá de la mayoría absoluta de los Asambleístas. Las decisiones de la Asamblea requerirán un mínimo del sesenta por ciento (60%) de los Asambleístas." },
      { tipo: 'articulo', numero: "128", texto: "Lo no previsto en estos Estatutos, será resuelto por el Junta Directiva de la Federación de Psicólogos de Venezuela. La Asamblea Nacional más próxima conocerá de las decisiones de la Junta Directiva para su consideración y aprobación." },
      { tipo: 'articulo', numero: "129", texto: "Se deroga el Reglamento Interno de la Federación de Psicólogos de Venezuela el cual queda sustituido por el presente Estatuto. Estos Estatutos entran en vigencia el 14 de Diciembre de dos mil trece, fecha en que fue aprobado en Asamblea Nacional Extraordinaria y deberá dársele publicidad. En la Asamblea Extraordinaria Federación de Psicólogos de Venezuela del 14-12-2013 se acordó, por unanimidad, autorizar a los cuatro miembros principales de la Junta Directiva, Presidenta Aminta Parra, Vicepresidente Jesús Sánchez, Secretaria General Myrna Benavides y Tesorera Elena Franklin de Martínez, para le den carácter auténtico con sus firmas a los Estatutos aprobados, con el fin de que presenten ante las autoridades competentes la solicitud de registro de los mismos y consignen los recaudos exigidos para dar curso a dicha solicitud. Aminta Parra Colmenárez Jesús Sánchez Sánchez CI 3.919.112, FPV 1.084 CI 3.194.891, FPV 4.791 Presidenta Vicepresidente Myrna Benavides Pérez Elena Franklin de Martínez CI 3.751.684, FPV 703 CI 2.934.375, FPV 3.965 Secretaria General Tesorera" },
    ],
  },
];
